CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, token text NOT NULL UNIQUE, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamp, refresh_token_expires_at timestamp, scope text, password text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS account_user_idx ON accounts(user_id);
CREATE TABLE IF NOT EXISTS verifications (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_settings (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS instruments (id text PRIMARY KEY, data jsonb NOT NULL, updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watchlists (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS watchlist_owner_idx ON watchlists(user_id);
CREATE TABLE IF NOT EXISTS watchlist_items (id text PRIMARY KEY, watchlist_id text NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, instrument_id text NOT NULL REFERENCES instruments(id), created_at timestamp NOT NULL DEFAULT now(), UNIQUE(watchlist_id,instrument_id));
CREATE TABLE IF NOT EXISTS chart_workspaces (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL, config jsonb NOT NULL, updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS workspace_owner_idx ON chart_workspaces(user_id);
CREATE TABLE IF NOT EXISTS portfolios (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,base_currency text NOT NULL,created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS portfolio_owner_idx ON portfolios(user_id);
CREATE TABLE IF NOT EXISTS portfolio_transactions (id text PRIMARY KEY,portfolio_id text NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE,instrument_id text NOT NULL REFERENCES instruments(id),type text NOT NULL CHECK(type IN ('BUY','SELL','DIVIDEND','DEPOSIT','WITHDRAWAL','SPLIT')),quantity numeric(38,18) NOT NULL CHECK(quantity>0),price numeric(38,18) NOT NULL CHECK(price>=0),fees numeric(38,18) NOT NULL DEFAULT 0 CHECK(fees>=0),currency text NOT NULL,date text NOT NULL,fx_rate numeric(38,18) CHECK(fx_rate>0),fx_kind text,fx_source text,broker text,notes text,created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS transaction_portfolio_idx ON portfolio_transactions(portfolio_id,date);
CREATE TABLE IF NOT EXISTS manual_quotes (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,instrument_id text NOT NULL REFERENCES instruments(id),price numeric(38,18) NOT NULL CHECK(price>0),as_of text NOT NULL,source text NOT NULL,UNIQUE(user_id,instrument_id));
CREATE TABLE IF NOT EXISTS exchange_rates (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,from_currency text NOT NULL,to_currency text NOT NULL,rate numeric(38,18) NOT NULL CHECK(rate>0),as_of text NOT NULL,source text NOT NULL,kind text NOT NULL,UNIQUE(user_id,from_currency,to_currency));
CREATE TABLE IF NOT EXISTS cedear_ratios (id text PRIMARY KEY,instrument_id text NOT NULL REFERENCES instruments(id),underlying_id text NOT NULL REFERENCES instruments(id),certificates_per_share numeric(28,12) NOT NULL CHECK(certificates_per_share>0),effective_from text NOT NULL,source text NOT NULL,retrieved_at timestamp NOT NULL DEFAULT now(),UNIQUE(instrument_id,effective_from));
CREATE TABLE IF NOT EXISTS ai_analyses (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,instrument_id text,report jsonb NOT NULL,created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS analysis_owner_idx ON ai_analyses(user_id,created_at);
CREATE TABLE IF NOT EXISTS request_limits (key text PRIMARY KEY,count integer NOT NULL,expires_at timestamp NOT NULL);
